from typing import List


def solveUserQuotaScheduling(input: str) -> List[str]:
    users = {}  # uid -> [quota, [(start, end), ...]]
    out = []
    for line in input.split('\n'):
        parts = line.split()
        if not parts:
            continue
        if parts[0] == 'CREATE_USER':
            users[parts[1]] = [int(parts[2]), []]
        elif parts[0] == 'ASSIGN':
            uid, s, e = parts[1], int(parts[3]), int(parts[4])
            quota, intervals = users[uid]
            if s >= e:  # zero-length: covers no time
                out.append('OK')
                continue
            events = []
            for a, b in intervals:
                if a < e and b > s:
                    events.append((max(a, s), 1))
                    events.append((min(b, e), -1))
            events.sort()  # (t, -1) sorts before (t, 1): half-open intervals
            cur = peak = 0
            for _, d in events:
                cur += d
                peak = max(peak, cur)
            if peak + 1 <= quota:
                intervals.append((s, e))
                out.append('OK')
            else:
                out.append('FAIL')
    return out
